// GLSL for the space scene: nebula clouds, the star field, and the planets.
// Everything is generated by maths in the browser — no image files are used for space.

const NOISE = /* glsl */ `
float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx);
}
float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = hash13(i), b = hash13(i + vec3(1, 0, 0));
  float c = hash13(i + vec3(0, 1, 0)), d = hash13(i + vec3(1, 1, 0));
  float e = hash13(i + vec3(0, 0, 1)), g = hash13(i + vec3(1, 0, 1));
  float h = hash13(i + vec3(0, 1, 1)), k = hash13(i + vec3(1, 1, 1));
  return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y), mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
}
float fbm(vec3 p, int oct) {
  float a = 0.5, s = 0.0, n = 0.0;
  for (int i = 0; i < oct; i++) {
    s += a * vnoise(p);
    n += a;
    p = p * 2.02 + vec3(17.13, 9.27, 5.31);
    a *= 0.5;
  }
  return s / n;
}
mat2 rot(float a) { float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }
`

export const QUAD_VS = /* glsl */ `#version 300 es
layout(location = 0) in vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
`

// ── Nebula: drawn small into a texture, then stretched over the screen ──────
export const NEBULA_FS = /* glsl */ `#version 300 es
precision highp float;
uniform vec2 uRes;
uniform vec3 uCam;
uniform float uTime;
uniform float uGalaxy;
out vec4 o;
${NOISE}
void main() {
  vec2 uv = (gl_FragCoord.xy / uRes - 0.5) * vec2(uRes.x / uRes.y, 1.0);
  vec3 p = vec3(uv * 1.15 + uCam.xy, uCam.z + uTime * 0.006);

  vec3 w = vec3(fbm(p * 1.2 + 3.1, 4), fbm(p * 1.2 + 7.7, 4), 0.0) - 0.5;
  vec3 q = p + w * 1.1;

  float body = fbm(q * 0.9, 5);
  float fine = fbm(q * 2.6 + 11.0, 5);
  float cloud = smoothstep(0.44, 0.78, body);
  float wisp = smoothstep(0.48, 0.82, fine) * cloud;
  float dust = smoothstep(0.50, 0.72, fbm(q * 1.9 + 41.0, 4));
  float hue = fbm(p * 0.55 + 23.0, 3);

  vec3 deep = vec3(0.030, 0.070, 0.190);
  vec3 cosmic = vec3(0.110, 0.250, 0.620);
  vec3 violet = vec3(0.200, 0.130, 0.420);

  vec3 col = cloud * mix(deep, violet, smoothstep(0.46, 0.66, hue)) * 0.8;
  col += wisp * mix(cosmic, violet * 1.3, smoothstep(0.52, 0.72, hue)) * 0.6;
  col *= 1.0 - 0.62 * dust;
  // faint glow along the densest ridges
  col += pow(wisp, 3.0) * vec3(0.30, 0.42, 0.75) * 0.3;
  // a far-off galaxy: a soft tilted disc with a brighter heart
  vec2 g = rot(0.5) * (uv - vec2(0.52, 0.27) + uCam.xy * 0.35);
  g.y *= 2.6;
  float gd = length(g);
  float arms = 0.6 + 0.4 * sin(atan(g.y, g.x) * 2.0 + gd * 38.0);
  col += (exp(-gd * 26.0) * 0.5 + exp(-gd * 9.0) * 0.12 * arms) * vec3(0.55, 0.66, 1.0) * uGalaxy;
  o = vec4(col, 1.0);
}
`

// ── Background: nebula texture + base colour + vignette + dithering ─────────
export const BACKDROP_FS = /* glsl */ `#version 300 es
precision highp float;
uniform sampler2D uNebula;
uniform vec2 uRes;
uniform float uNebulaAmount;
uniform float uDim;
out vec4 o;
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  vec3 base = mix(vec3(0.008, 0.011, 0.028), vec3(0.016, 0.024, 0.058), smoothstep(0.0, 1.0, uv.y));
  vec3 col = base + texture(uNebula, uv).rgb * uNebulaAmount;
  vec2 c = uv - 0.5;
  col *= 1.0 - 0.55 * smoothstep(0.25, 0.95, length(c * vec2(1.0, 1.15)));
  col *= 1.0 - uDim;
  col += (hash12(gl_FragCoord.xy) - 0.5) / 255.0;
  o = vec4(col, 1.0);
}
`

// ── Stars: real depth, so travelling forward makes them rush past ───────────
export const STAR_VS = /* glsl */ `#version 300 es
layout(location = 0) in vec2 aCorner;
layout(location = 1) in vec3 aPos;
layout(location = 2) in vec4 aRnd;
uniform vec2 uRes;      // drawing buffer size
uniform vec2 uBox;      // lateral size of the star volume at the far plane
uniform vec3 uCam;
uniform vec3 uStreak;   // how far the camera moved recently
uniform float uScale;   // device pixel scale
uniform float uTime;
uniform float uAmount;
out vec2 vLocal;
out float vHalf;
out float vSize;
out float vBright;
out vec3 vTint;
out float vSpike;

const float Z_NEAR = 0.09;

void main() {
  vec2 xy = mod(aPos.xy * uBox - uCam.xy, uBox) - uBox * 0.5;
  float z = Z_NEAR + (1.0 - Z_NEAR) * fract(aPos.z - uCam.z);

  vec2 p0 = xy / z;
  float z1 = max(z + uStreak.z, 0.03);
  vec2 p1 = (xy + uStreak.xy) / z1;

  float spike = step(0.985, aRnd.x);
  float size = (0.55 + 1.5 * aRnd.x * aRnd.x) * mix(1.0, 2.1, smoothstep(0.55, 0.1, z));
  size = (size + spike * 1.6) * uScale;
  float quad = size * mix(2.4, 9.0, spike);

  vec2 d = p1 - p0;
  float len = length(d);
  vec2 dir = len > 0.001 ? d / len : vec2(1.0, 0.0);
  vec2 nrm = vec2(-dir.y, dir.x);
  vec2 mid = (p0 + p1) * 0.5;
  float halfLen = len * 0.5;
  vec2 pos = mid + dir * aCorner.x * (halfLen + quad) + nrm * aCorner.y * quad;

  vLocal = vec2(aCorner.x * (halfLen + quad), aCorner.y * quad);
  vHalf = halfLen;
  vSize = size;
  vSpike = spike;

  float fade = smoothstep(1.0, 0.86, z) * smoothstep(Z_NEAR, Z_NEAR + 0.05, z);
  float twinkle = 0.82 + 0.18 * sin(uTime * (0.6 + aRnd.w * 1.7) + aRnd.z * 6.283);
  float bright = (0.22 + 0.78 * aRnd.y * aRnd.y) * mix(0.55, 1.0, smoothstep(1.0, 0.2, z));
  vBright = bright * fade * twinkle * uAmount * (size / (size + halfLen * 0.35));
  vTint = mix(vec3(0.78, 0.86, 1.0), vec3(1.0, 0.93, 0.84), step(0.82, aRnd.z));
  vTint = mix(vTint, vec3(0.72, 0.78, 1.0), step(0.93, aRnd.w));

  gl_Position = vec4(pos / (uRes * 0.5), 0.0, 1.0);
}
`

export const STAR_FS = /* glsl */ `#version 300 es
precision highp float;
in vec2 vLocal;
in float vHalf;
in float vSize;
in float vBright;
in vec3 vTint;
in float vSpike;
out vec4 o;
void main() {
  vec2 q = vec2(max(abs(vLocal.x) - vHalf, 0.0), vLocal.y);
  float d = length(q) / vSize;
  float core = exp(-d * d * 1.6);
  float glow = 0.18 / (1.0 + d * d * 2.5);
  float a = core + glow * smoothstep(2.4, 0.6, d);
  // four-point sparkle on the few brightest stars
  vec2 s = abs(vLocal) / vSize;
  float rays = exp(-s.y * 3.2) * exp(-s.x * 0.55) + exp(-s.x * 3.2) * exp(-s.y * 0.55);
  a += vSpike * rays * 0.55 * smoothstep(9.0, 3.0, max(s.x, s.y));
  o = vec4(vTint * a * vBright, 0.0);
}
`

// ── Planets ─────────────────────────────────────────────────────────────────
export const BODY_VS = /* glsl */ `#version 300 es
layout(location = 0) in vec2 aPos;
uniform vec2 uRes;
uniform vec2 uCenter;
uniform float uExtent;
void main() {
  vec2 px = uCenter + aPos * uExtent;
  gl_Position = vec4(px / uRes * 2.0 - 1.0, 0.0, 1.0);
}
`

export const BODY_FS = /* glsl */ `#version 300 es
precision highp float;
uniform vec2 uCenter;
uniform float uRadius;
uniform int uType;       // 0 chrome · 1 gas · 2 rock · 3 terra · 4 lava · 5 ice
uniform vec3 uC0;
uniform vec3 uC1;
uniform vec3 uC2;
uniform vec3 uAtmo;
uniform float uSeed;
uniform float uSpin;
uniform float uTilt;
uniform vec3 uLight;
uniform float uAlpha;
uniform float uDetail;
uniform float uGlow;
uniform float uHaze;
uniform float uCloud;    // cloud cover for ocean worlds, 0–1     // 1 = normal halo; higher = thinner (for a horizon seen from low orbit)
uniform float uTime;
uniform vec4 uRing;      // inner, outer, tilt toward viewer, roll
uniform vec3 uRingCol;
uniform float uRingOn;
out vec4 o;
${NOISE}

float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

// How much the surface position changes from one pixel to the next.
float gFoot = 0.0;
// fbm whose finest octaves fade out once they get smaller than a pixel (no shimmer).
// k = how many times p is scaled relative to the unit sphere.
float fbmL(vec3 p, int oct, float k) {
  float a = 0.5, s = 0.0, n = 0.0, f = k * gFoot;
  for (int i = 0; i < oct; i++) {
    float w = smoothstep(0.9, 2.6, 1.0 / max(f, 1e-5));
    s += a * mix(0.5, vnoise(p), w);
    n += a;
    p = p * 2.02 + vec3(17.13, 9.27, 5.31);
    f *= 2.02;
    a *= 0.5;
  }
  return s / n;
}

// Nearest random point in a 3D grid, used for craters: xyz = direction to it, w = distance.
float gW2 = 8.0;
vec4 worley(vec3 p) {
  vec3 i = floor(p), f = fract(p);
  float d = 8.0;
  float d2 = 8.0;
  vec3 v = vec3(0.0);
  for (int x = -1; x <= 1; x++)
    for (int y = -1; y <= 1; y++)
      for (int z = -1; z <= 1; z++) {
        vec3 g = vec3(float(x), float(y), float(z));
        vec3 r = g + hash33(i + g) - f;
        float dd = dot(r, r);
        if (dd < d) { d2 = d; d = dd; v = r; }
        else if (dd < d2) { d2 = dd; }
      }
  d = sqrt(d);
  gW2 = sqrt(d2);
  return vec4(v / max(d, 1e-4), d);
}

// Slope of a smooth three-octave height field, for shading broad relief.
vec3 slope3(vec3 p, float k, float f0) {
  const float e = 0.09;
  return vec3(
    fbmL(p + vec3(e, 0.0, 0.0), 3, k) - f0,
    fbmL(p + vec3(0.0, e, 0.0), 3, k) - f0,
    fbmL(p + vec3(0.0, 0.0, e), 3, k) - f0
  ) * (k / e);
}

float ringDensity(float t) {
  float bands = 0.55 + 0.45 * sin(t * 38.0 + uSeed) * sin(t * 13.0 + uSeed * 2.0);
  bands *= 0.75 + 0.25 * sin(t * 97.0);
  float gap = smoothstep(0.035, 0.0, abs(t - 0.58)) * 0.85 + smoothstep(0.02, 0.0, abs(t - 0.27)) * 0.5;
  float edge = smoothstep(0.0, 0.05, t) * smoothstep(1.0, 0.93, t);
  return clamp(bands * (1.0 - gap), 0.0, 1.0) * edge * mix(0.65, 1.0, t);
}

// bump = how the surface normal leans because of relief (in the planet's own space)
struct Surface { vec3 albedo; vec3 emissive; vec3 bump; float spec; float gloss; };

// A thin line where a noise field crosses its midpoint (cracks, fissures),
// drawn with soft edges at least a couple of pixels wide so it never looks jagged.
float vein(float f, float w) {
  float d = abs(2.0 * f - 1.0);
  float aa = max(fwidth(f) * 2.5, 0.012);
  return 1.0 - smoothstep(w, w + aa, d);
}

Surface chromeSurface(vec3 s, vec3 n) {
  Surface S;
  // liquid metal: the mirror surface ripples very slowly
  vec3 q = s * 1.15 + vec3(0.0, uTime * 0.018, uSeed);
  vec3 ripple = vec3(fbmL(q, 3, 1.15), fbmL(q + 7.3, 3, 1.15), fbmL(q + 13.1, 3, 1.15)) - 0.5;
  vec3 nn = normalize(n + ripple * 0.46);
  vec3 r = reflect(vec3(0.0, 0.0, -1.0), nn);
  float y = r.y;
  // classic chrome: a bright horizon, the sky deepening above it, dark ground lifting to steel below
  vec3 sky = mix(uC2, uC1, smoothstep(0.0, 0.42, y));
  sky = mix(sky, uC0 * 2.2 + vec3(0.01, 0.02, 0.05), smoothstep(0.38, 0.98, y));
  vec3 ground = mix(uC0 * 0.3, mix(uC1, uC2, 0.25) * 0.85, smoothstep(-0.04, -0.98, y));
  vec3 env = mix(ground, sky, smoothstep(-0.018, 0.018, y));
  env += uC2 * pow(max(dot(r, normalize(uLight + vec3(0.0, 0.15, 0.35))), 0.0), 48.0) * 0.75;
  S.albedo = env;
  S.emissive = vec3(0.0);
  S.bump = vec3(0.0);
  S.spec = 0.0;
  S.gloss = 1.0;
  return S;
}

Surface gasSurface(vec3 s) {
  Surface S;
  float warp = fbmL(s * vec3(2.0, 5.0, 2.0) + uSeed, 4, 5.0) - 0.5;
  float lat = s.y + warp * 0.20;
  float swirl = fbmL(vec3(s.x * 2.6, lat * 11.0, s.z * 2.6) + uSeed * 1.7, 5, 11.0);
  float bands = sin(lat * 15.0 + swirl * 3.4 + uSeed) * 0.5 + 0.5;
  float fine = fbmL(vec3(s.x * 7.0, lat * 46.0, s.z * 7.0) + uSeed, 4, 46.0);
  float t = clamp(bands * 0.72 + fine * 0.42 - 0.08, 0.0, 1.0);
  vec3 c = mix(uC0, uC1, smoothstep(0.05, 0.55, t));
  c = mix(c, uC2, smoothstep(0.58, 0.98, t));
  // one long-lived storm
  vec3 sc = normalize(vec3(cos(uSeed * 3.0), -0.32, sin(uSeed * 3.0)));
  vec3 dv = s - sc;
  float storm = smoothstep(0.26, 0.05, length(dv * vec3(1.0, 2.1, 1.0)));
  c = mix(c, mix(uC2, uC1, 0.35) * 1.05, storm * 0.7);
  c *= 0.9 + 0.2 * fine;
  S.albedo = c;
  S.emissive = vec3(0.0);
  S.bump = vec3(0.0);
  S.spec = 0.0;
  S.gloss = 0.0;
  return S;
}

Surface rockSurface(vec3 s) {
  Surface S;
  float k = 2.1 * uDetail;
  vec3 p = s * k + uSeed;
  float h = fbmL(p, 6, k);
  float h2 = fbmL(p * 3.1 + 5.0, 5, k * 3.1);
  float broad = fbmL(p, 3, k);
  vec4 cw = worley(s * 3.4 * uDetail + uSeed * 0.7);
  float w = cw.w;
  float whole = smoothstep(0.03, 0.30, gW2 - w); // 0 at the border between two craters
  float bowl = smoothstep(0.38, 0.16, w) * whole;
  float wall = smoothstep(0.08, 0.30, w) * smoothstep(0.42, 0.34, w) * whole;
  float lip = smoothstep(0.34, 0.40, w) * smoothstep(0.54, 0.42, w) * whole;
  float t = h * 0.68 + h2 * 0.32;
  vec3 c = mix(uC0, uC1, smoothstep(0.30, 0.62, t));
  c = mix(c, uC2, smoothstep(0.60, 0.86, t) * 0.8);
  c *= 1.0 - bowl * 0.26;
  c += lip * uC2 * 0.10;
  S.albedo = c;
  S.emissive = vec3(0.0);
  // crater walls lean toward the crater centre, the outer lip leans away; plus broad terrain
  S.bump = cw.xyz * (wall * 0.62 - lip * 0.34) - slope3(p, k, broad) * 0.075;
  S.spec = 0.0;
  S.gloss = 0.0;
  return S;
}

Surface terraSurface(vec3 s, vec3 sCloud) {
  Surface S;
  float k = 1.5 * uDetail;
  vec3 p = s * k + uSeed;
  float cont = fbmL(p, 6, k) + (fbmL(p * 4.0 + 3.0, 4, k * 4.0) - 0.5) * 0.18;
  float soft = max(0.014, gFoot * k * 1.4);
  float land = smoothstep(0.53 - soft, 0.53 + soft, cont);
  vec3 ocean = mix(uC0 * 0.55, uC1, smoothstep(0.34, 0.53, cont));
  float elev = smoothstep(0.54, 0.75, cont);
  vec3 ground = mix(uC2, uC2 * 0.45 + vec3(0.10, 0.08, 0.05), elev);
  ground = mix(ground, ground * 0.6, fbmL(p * 6.0, 3, k * 6.0));
  vec3 c = mix(ocean, ground, land);
  float cap = smoothstep(0.80, 0.92, abs(s.y) + (fbmL(p * 3.0, 3, k * 3.0) - 0.5) * 0.2);
  c = mix(c, vec3(0.92, 0.95, 1.0), cap);
  float kc = 2.6 * uDetail;
  vec3 cp = sCloud * kc + uSeed * 2.0;
  float cl = fbmL(cp + (fbmL(cp * 2.0, 3, kc * 2.0) - 0.5) * 0.9, 5, kc * 1.6);
  float cover = mix(0.74, 0.44, uCloud);
  float clouds = smoothstep(cover, cover + 0.2, cl);
  c = mix(c, vec3(0.96, 0.97, 1.0), clouds * 0.9);
  S.albedo = c;
  S.emissive = vec3(0.0);
  float broad = fbmL(p, 3, k);
  S.bump = -slope3(p, k, broad) * 0.07 * land * (1.0 - clouds);
  S.spec = (1.0 - land) * (1.0 - clouds) * (1.0 - cap);
  S.gloss = 0.0;
  return S;
}

Surface lavaSurface(vec3 s) {
  Surface S;
  float k = 2.2 * uDetail;
  vec3 p = s * k + uSeed;
  float h = fbmL(p, 6, k);
  float broad = fbmL(p, 3, k);
  float f1 = fbmL(p * 1.5 + 7.0, 5, k * 1.5);
  float f2 = fbmL(p * 3.6 + 2.0, 4, k * 3.6);
  float glowLine = 1.0 - abs(2.0 * f1 - 1.0);
  float cracks = vein(f1, 0.03) + pow(glowLine, 5.0) * 0.45 + vein(f2, 0.025) * 0.5;
  float pools = smoothstep(0.60, 0.74, fbmL(p * 0.9 + 31.0, 4, k * 0.9));
  float pulse = 0.82 + 0.18 * sin(uTime * 0.45 + h * 14.0);
  vec3 crust = mix(uC0, uC1, smoothstep(0.32, 0.72, h));
  float heat = clamp(cracks + pools * (0.5 + 0.5 * glowLine), 0.0, 1.4);
  S.albedo = crust * (1.0 - 0.6 * clamp(heat, 0.0, 1.0));
  S.emissive = (uC2 * heat + vec3(1.0, 0.85, 0.6) * pow(clamp(heat, 0.0, 1.0), 4.0) * 0.5) * pulse;
  S.bump = -slope3(p, k, broad) * 0.085;
  S.spec = 0.0;
  S.gloss = 0.0;
  return S;
}

Surface iceSurface(vec3 s) {
  Surface S;
  float k = 1.9 * uDetail;
  vec3 p = s * k + uSeed;
  float h = fbmL(p, 6, k);
  float broad = fbmL(p, 3, k);
  float f1 = fbmL(p * 1.7 + 4.0, 5, k * 1.7);
  float f2 = fbmL(p * 4.2 + 9.0, 4, k * 4.2);
  float cracks = vein(f1, 0.035) + vein(f2, 0.022) * 0.55;
  float maria = smoothstep(0.55, 0.69, fbmL(p * 0.8 + 13.0, 4, k * 0.8));
  vec3 c = mix(uC1, uC2, smoothstep(0.30, 0.66, h));
  c = mix(c, uC0 * 1.6 + 0.03, maria * 0.82);
  c = mix(c, uC0, clamp(cracks, 0.0, 1.0) * 0.88);
  S.albedo = c;
  S.emissive = vec3(0.0);
  S.bump = -slope3(p, k, broad) * 0.06;
  S.spec = 0.35 * (1.0 - maria);
  S.gloss = 0.0;
  return S;
}

void main() {
  vec2 p = (gl_FragCoord.xy - uCenter) / uRadius;
  float r = length(p);
  vec3 L = normalize(uLight);
  float aa = 1.5 / uRadius;

  vec3 col = vec3(0.0);
  float alpha = 0.0;

  // Soft glow of the atmosphere outside the disc, stronger on the sunlit side.
  if (r > 1.0 - aa * 3.0) {
    float d = max(r - 1.0, 0.0);
    float side = smoothstep(-0.75, 0.55, dot(vec3(p / max(r, 0.0001), 0.0), L));
    float halo = exp(-d * 11.0 * uHaze) * 0.55 + exp(-d * 3.2 * uHaze) * 0.10;
    col = uAtmo * halo * (0.12 + 0.88 * side) * uGlow;
  }

  // Ring: where this pixel's line of sight crosses the ring plane.
  float ringA = 0.0;
  vec3 ringC = vec3(0.0);
  float ringFront = 0.0;
  vec3 N = vec3(0.0, cos(uRing.z), sin(uRing.z));
  N.xy = rot(uRing.w) * N.xy;
  if (uRingOn > 0.5) {
    float zr = -(N.x * p.x + N.y * p.y) / N.z;
    vec3 q = vec3(p, zr);
    float d = length(q);
    if (d > uRing.x && d < uRing.y) {
      float t = (d - uRing.x) / (uRing.y - uRing.x);
      float dens = ringDensity(t);
      float b = dot(q, L);
      float shadow = (b < 0.0 && dot(q, q) - b * b < 1.0) ? 0.06 : 1.0;
      float lit = 0.5 + 0.5 * abs(dot(N, L));
      float grain = 0.9 + 0.2 * hash12(gl_FragCoord.xy);
      ringC = uRingCol * mix(0.55, 1.1, sin(t * 21.0 + uSeed) * 0.5 + 0.5) * lit * shadow * grain;
      ringA = dens * 0.92;
      ringFront = step(0.0, zr);
    }
  }

  if (r < 1.0) {
    float z = sqrt(1.0 - r * r);
    vec3 n = vec3(p, z);
    vec3 s = n;
    s.xy = rot(-uTilt) * s.xy;
    vec3 sc = s;
    s.xz = rot(uSpin) * s.xz;
    sc.xz = rot(uSpin * 1.35 + 1.0) * sc.xz;
    gFoot = (1.0 / uRadius) / max(z, 0.03);

    Surface S;
    if (uType == 0) S = chromeSurface(s, n);
    else if (uType == 1) S = gasSurface(s);
    else if (uType == 2) S = rockSurface(s);
    else if (uType == 3) S = terraSurface(s, sc);
    else if (uType == 4) S = lavaSurface(s);
    else S = iceSurface(s);

    // Relief: bring the lean of the surface back into view space and tilt the normal by it.
    vec3 bv = S.bump;
    bv.xz = rot(-uSpin) * bv.xz;
    bv.xy = rot(uTilt) * bv.xy;
    bv -= n * dot(n, bv);
    vec3 nb = normalize(n + bv);

    float ndl = dot(nb, L);
    float day = smoothstep(-0.10, 0.42, ndl);
    float dayFlat = smoothstep(-0.15, 0.35, dot(n, L));

    // Shadow the ring casts on the planet.
    float ringShade = 1.0;
    if (uRingOn > 0.5) {
      float dn = dot(N, L);
      if (abs(dn) > 0.0001) {
        float t = -dot(N, n) / dn;
        if (t > 0.0) {
          float hd = length(n + L * t);
          if (hd > uRing.x && hd < uRing.y) ringShade = 1.0 - 0.6 * ringDensity((hd - uRing.x) / (uRing.y - uRing.x));
        }
      }
    }

    vec3 base = pow(S.albedo, vec3(2.2));
    vec3 lit = base * (day * 1.15 * ringShade + 0.012);
    lit *= mix(0.72, 1.0, pow(z, 0.45));                       // limb darkening
    lit = mix(lit, base * (0.35 + 0.75 * dayFlat), S.gloss);    // polished metal keeps its reflections
    vec3 h = normalize(L + vec3(0.0, 0.0, 1.0));
    lit += vec3(1.0, 0.97, 0.9) * pow(max(dot(nb, h), 0.0), 60.0) * S.spec * 0.9 * day;
    lit += pow(S.emissive, vec3(2.2)) * (0.55 + 0.45 * (1.0 - dayFlat));

    // Atmosphere: thin bright rim on the day side, a whisper on the night side.
    float rimPow = 2.6 * sqrt(uHaze);
    float fres = pow(1.0 - z, rimPow);
    vec3 atmo = pow(uAtmo, vec3(2.2));
    lit += atmo * fres * (0.05 + 0.95 * dayFlat) * 0.9 * uGlow;
    lit += atmo * pow(1.0 - z, rimPow * 2.7) * 0.10 * uGlow;

    // gentle highlight roll-off so bright clouds and rims never burn out to flat white
    lit = 1.0 - exp(-max(lit, 0.0) * 1.35);
    vec3 surf = pow(lit, vec3(1.0 / 2.2));
    float sideIn = smoothstep(-0.75, 0.55, dot(vec3(p / max(r, 0.0001), 0.0), L));
    vec3 haloEdge = uAtmo * 0.65 * (0.12 + 0.88 * sideIn) * uGlow;
    float melt = min(9.0 / uRadius, 0.006) * step(0.01, uGlow);
    surf = mix(surf, haloEdge, smoothstep(1.0 - melt, 1.0, r));
    float edge = smoothstep(1.0, 1.0 - aa * 2.0, r);
    col = mix(col, surf, edge);
    alpha = edge;

    if (ringA > 0.0 && ringFront > 0.5) {
      col = mix(col, ringC, ringA);
    }
  } else if (ringA > 0.0) {
    col = mix(col, ringC, ringA);
    alpha = max(alpha, ringA);
  }

  col += (hash12(gl_FragCoord.xy + 17.0) - 0.5) / 255.0;
  o = vec4(col * uAlpha, alpha * uAlpha);
}
`
